<script setup lang="ts">import {computed} from 'vue';import type {EChartsOption} from 'echarts';import BaseChart from '@/components/BaseChart.vue';import ScreenPanel from './ScreenPanel.vue';import type {DashboardRisk,DashboardScenario} from '@/types';const props=defineProps<{scenarios:DashboardScenario[];risk:DashboardRisk}>();const carbonChart=computed<EChartsOption>(()=>({xAxis:{type:'category',data:props.scenarios.map(x=>x.name)},yAxis:{type:'value'},series:[{type:'bar',name:'累计碳排',data:props.scenarios.map(x=>x.cumulative_carbon_emission_t)}]}));const scatterChart=computed<EChartsOption>(()=>({xAxis:{name:'投资'},yAxis:{name:'减排'},series:[{type:'scatter',data:props.scenarios.map(x=>[x.investment,x.cumulative_carbon_reduction_t])}]}));const riskChart=computed<EChartsOption>(()=>({series:[{type:'pie',radius:['40%','70%'],data:[{name:'高',value:props.risk.high},{name:'中',value:props.risk.medium},{name:'低',value:props.risk.low}]}]}));</script>
<template><ScreenPanel title="多场景仿真比较" link="/scenarios" :empty="!scenarios.length" empty-text="暂无多场景推演结果"><div class="dual-chart"><BaseChart :option="carbonChart" height="190px"/><BaseChart :option="scatterChart" height="190px"/></div><div class="scenario-mini"><span v-for="s in scenarios" :key="s.scenario_version_id"><b>{{s.name}} {{s.baseline?'· BASELINE':''}}</b>{{s.type}} · 减排率 {{s.reduction_rate==null?'--':`${(s.reduction_rate*100).toFixed(1)}%`}} · 电费 {{s.total_electricity_cost??'--'}}</span></div></ScreenPanel><ScreenPanel title="风险状态" link="/risks" :empty="!risk.run" empty-text="未评估"><div class="risk-row"><BaseChart :option="riskChart" height="170px"/><div><b>最高风险 {{risk.run?.overall_level}}</b><span>高 {{risk.high}} / 中 {{risk.medium}} / 低 {{risk.low}}</span><small>{{risk.run?.results.filter(x=>x.level==='HIGH').map(x=>x.category).join('、')||'无高风险类别'}}</small></div></div></ScreenPanel></template>
